<script setup lang="ts">
import { reactive, ref } from 'vue';
import { router } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import { ShieldCheck } from '@lucide/vue';
const props = defineProps<{ user: { id: number; name: string }; factories: Array<{ id: number; name: string }> }>();
const form = reactive({ role: '', factory_id: '' });
const saving = ref(false);
const error = ref('');
const submit = () => { if (!form.role) { error.value = 'Pilih peran terlebih dahulu.'; return; } saving.value = true; router.post(route('pending-role.submit'), form, { onSuccess: () => { saving.value = false; }, onError: () => { saving.value = false; error.value = 'Gagal mengirim permintaan.'; } }); };
</script>
<template><div class="flex min-h-screen items-center justify-center bg-slate-50 px-4 py-10"><div class="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="mb-5 flex items-center gap-3"><div class="flex h-11 w-11 items-center justify-center rounded-xl bg-orange-100 text-orange-600"><ShieldCheck :size="24" /></div><div><h1 class="text-lg font-extrabold">Halo, {{ user.name }}</h1><p class="text-xs text-slate-500">Aktivasi akun SI KARTO</p></div></div><p class="mb-5 text-sm leading-6 text-slate-600">Akun Anda sudah terhubung dengan SSO, tetapi belum diaktifkan Admin. Pilih peran untuk mengirim permintaan persetujuan.</p><div v-if="error" class="mb-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{{ error }}</div><div class="space-y-4"><label class="field-block"><span class="field-label">Pilih Peran</span><select v-model="form.role" class="control"><option value="">Pilih peran</option><option value="super_admin">Super Admin</option><option value="admin">Admin</option><option value="inspector">Inspector / QA</option><option value="user">User</option></select></label><label class="field-block"><span class="field-label">Factory (opsional)</span><select v-model="form.factory_id" class="control"><option value="">Pilih factory</option><option v-for="factory in factories" :key="factory.id" :value="factory.id">{{ factory.name }}</option></select></label><button class="primary-button" :disabled="saving" @click="submit">{{ saving ? 'Mengirim...' : 'Kirim Permintaan' }}</button></div><p class="mt-5 text-center text-xs leading-5 text-slate-400">Setelah dikirim, tunggu persetujuan Admin untuk mulai menggunakan SI KARTO.</p></div></div></template>
<style scoped>.field-block{display:flex;flex-direction:column;gap:.4rem}.field-label{font-size:.75rem;font-weight:600;color:#64748b}.control{height:2.75rem;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:0 .75rem;font-size:.875rem;color:#172033;outline:none}.control:focus{border-color:#fb923c;box-shadow:0 0 0 3px #fed7aa}.primary-button{width:100%;border-radius:.625rem;background:#f97316;padding:.75rem 1rem;color:#fff;font-size:.875rem;font-weight:700}.primary-button:disabled{opacity:.5}</style>
